81	std::string one_line(std::string text)
82	{
83	    for (char& c : text)
84	        if (c == '\r' || c == '\n' || c == '\t')
85	            c = ' ';
86	    std::string out;
87	    for (char c : text)
88	        if (c != ' ' || (!out.empty() && out.back() != ' '))
89	            out += c;
90	    while (!out.empty() && out.back() == ' ')
91	        out.pop_back();
92	    constexpr std::size_t kLimit = 240;
93	    if (out.size() > kLimit)
94	        out = out.substr(0, kLimit) + "...";
95	    return out;
