107	// The request gives up after kConnectionWait: upstream's has no upper limit
108	// (Http's DEFAULT_TIMEOUT_MAX is 0), so a host that accepts the connection and
109	// never replies would hold the test, and the chat's tool call, for good. And
110	// the HTTP status and the host's own words come back, where upstream returns
111	// a message that puts a cause on curl's error and only logs Klipper's state.
112	// The requests and checks are upstream's: when Moonraker::test or
113	// OctoPrint::test changes, change these.
114	class MoonrakerTest : public Moonraker
115	{
116	public:
117	    using Moonraker::Moonraker;
118	
119	    HostAnswer answer() const
120	    {
121	        HostAnswer answer{true};
122	        auto       http = Http::get(make_url("server/info"));
123	        set_auth(http);
124	        http.timeout_max(kConnectionWait.count())
125	            .on_error([&](std::string body, std::string error, unsigned status) { record_error(answer, body, error, status); })
126	            .on_complete([&](std::string body, unsigned) {
127	                try {
128	                    std::stringstream           stream(body);
129	                    boost::property_tree::ptree tree;
130	                    boost::property_tree::read_json(stream, tree);
131	                    const auto klippy_state = tree.get_optional<std::string>("result.klippy_state");
132	                    if (!klippy_state) {
133	                        answer = {false, 0, "The host responded but it doesn't look like Moonraker (missing result.klippy_state)."};
134	                        return;
135	                    }
136	                    answer.said = *klippy_state;
137	                } catch (const std::exception& ex) {
138	                    answer = {false, 0, std::string("Could not parse Moonraker server response: ") + ex.what()};
139	                }
140	            })
141	#ifdef WIN32
142	            .ssl_revoke_best_effort(m_ssl_revoke_best_effort)
143	#endif
144	            .perform_sync();
145	        return answer;
146	    }
147	};
